function timing(header){const parts=(header??'').split(',').map(s=>s.trim()),r={};for(const key of['auth','load','db','db_max']){const matches=parts.filter(x=>x.startsWith(key+';'));assert(matches.length===1,'TIMING_MISSING_OR_DUPLICATE');const m=new RegExp('^'+key+';dur=(\\d+(?:\\.\\d+)?)$').exec(matches[0]);assert(m,'INVALID_TIMING');r[key]=Number(m[1]);}const http=parts.filter(x=>x.startsWith('db_http;'));assert(http.length===1);const m=/^db_http;desc="(\d+)"$/.exec(http[0]);assert(m);r.db_http=Number(m[1]);r.serverTotalMs=r.auth+r.load;return r;}
// Controls test the actual parser used by the live probe; missing/corrupt timing cannot become0.
