 for(let i=0;i<3;i++){const professional=data.professionals[i];const prepared=await app('creation_prepare','/odonto/disponibilidad/slots?'+new URLSearchParams({service_id:data.services[0],professional_id:professional,from:date,to:date}));const slot=prepared.slots[0];assert(/^\d{4}-\d{2}-\d{2}$/.test(slot.date)&&/^\d{2}:\d{2}$/.test(slot.time));const key=randomUUID();const payload=await app('create_appointment','/odonto/agenda?/create_appointment',{service_id:data.services[0],professional_id:professional,date:slot.date,time:slot.time,patient_mode:'existing',patient_id:patient,idempotency_key:key});assert(payload.type==='redirect');const matched=/^\/odonto\/turnos\/([a-f0-9-]{36})\?/.exec(payload.location);assert(matched,'UNEXPECTED_CREATED_LOCATION');const id=matched[1];const read=JSON.parse(productionPsql(database,`begin transaction read only;select json_build_object('owned',(select count(*)from public.appointments where id='${id}'::uuid and business_id='${data.business}'::uuid and patient_id='${patient}'::uuid),'total',(select count(*)from public.appointments where business_id='${data.business}'::uuid));commit;`,{application:'cita_suite_targeted_created_readback',timeout:20000}));assert(read.owned===1);result.created.push({ownedReadback:true,ordinal:i+1,fixtureAppointments:read.total});save();}
 async function component(name,path,body,admin=false){const token=admin?serviceKey:access,apiKey=admin?serviceKey:anonKey;const t=performance.now(),response=await fetch(PRODUCTION_API_ORIGIN+'/rest/v1/'+path,{method:body?'POST':'GET',headers:{authorization:'Bearer '+token,apikey:apiKey,'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)});const headersMs=performance.now()-t,payload=await response.json();assert(response.ok,'COMPONENT_FAILED_'+name);result.components.push({at:new Date().toISOString(),name,headersMs:Math.round(headersMs*10)/10,clientBodyMs:Math.round((performance.now()-t)*10)/10,rows:Array.isArray(payload)?payload.length:null});save();return payload;}
